select m.id, m.title, m.author, m.summary, m.content, m.original_url, m.original_id, m.reply_count, m.like_count, m.dislike_count, m.view_count, m.share_count, m.comment_count, m.publish_time, m.content_type, m.package_type, m.status, m.is_top, m.source, m.cover_image, m.video_url, m.online_time, m.offline_time, m.top_time, m.untop_time, m.create_by, m.create_time, m.update_by, m.update_time, m.remark from core_material m inner join core_material_tag mt on m.id = mt.material_id where mt.tag_id = #{tagId}
and m.status = #{status}
and m.package_type <= #{maxPackageType}
order by m.is_top desc, m.publish_time desc

