UPDATE core_material
SET view_count = IFNULL(view_count, 0) + 1
WHERE id = #{id}

UPDATE core_material
SET like_count = IFNULL(like_count, 0) + 1
WHERE id = #{id}

UPDATE core_material
SET like_count = CASE WHEN IFNULL(like_count, 0) > 0 THEN like_count - 1 ELSE 0 END
WHERE id = #{id}

UPDATE core_material
SET dislike_count = IFNULL(dislike_count, 0) + 1
WHERE id = #{id}

UPDATE core_material
SET dislike_count = CASE WHEN IFNULL(dislike_count, 0) > 0 THEN dislike_count - 1 ELSE 0 END
WHERE id = #{id}
